import{_ as l,H as e,f as i,i as r}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"第三法典","description":"","frontmatter":{"title":"第三法典","outline":"deep"},"headers":[],"relativePath":"rules3.md","filePath":"rules3.md"}'),o={name:"rules3.md"};function h(t,a,n,d,s,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="第三法典" tabindex="-1">第三法典 <a class="header-anchor" href="#第三法典" aria-label="Permalink to &quot;第三法典&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PIGLIN KINGDOM 大法典 第三法典（第101条～第150条）</p></div><h1 id="第三十七編-貴族法" tabindex="-1">第三十七編 貴族法 <a class="header-anchor" href="#第三十七編-貴族法" aria-label="Permalink to &quot;第三十七編 貴族法&quot;">​</a></h1><h2 id="第一章-貴族制度" tabindex="-1">第一章 貴族制度 <a class="header-anchor" href="#第一章-貴族制度" aria-label="Permalink to &quot;第一章 貴族制度&quot;">​</a></h2><h3 id="第101条-貴族" tabindex="-1">第101条 貴族 <a class="header-anchor" href="#第101条-貴族" aria-label="Permalink to &quot;第101条 貴族&quot;">​</a></h3><ol><li>王国は貴族制度を認める。</li><li>貴族は王室への忠誠義務を負う。</li><li>貴族の爵位は勅令によって授与される。</li></ol><h3 id="第102条-爵位" tabindex="-1">第102条 爵位 <a class="header-anchor" href="#第102条-爵位" aria-label="Permalink to &quot;第102条 爵位&quot;">​</a></h3><ol><li>公爵</li><li>侯爵</li><li>伯爵</li><li>子爵</li><li>男爵</li></ol><h3 id="第103条-継承" tabindex="-1">第103条 継承 <a class="header-anchor" href="#第103条-継承" aria-label="Permalink to &quot;第103条 継承&quot;">​</a></h3><ol><li>爵位は世襲とする。</li><li>国王は爵位を剥奪できる。</li></ol><hr><h1 id="第三十八編-騎士法" tabindex="-1">第三十八編 騎士法 <a class="header-anchor" href="#第三十八編-騎士法" aria-label="Permalink to &quot;第三十八編 騎士法&quot;">​</a></h1><h2 id="第一章-王立騎士団" tabindex="-1">第一章 王立騎士団 <a class="header-anchor" href="#第一章-王立騎士団" aria-label="Permalink to &quot;第一章 王立騎士団&quot;">​</a></h2><h3 id="第104条-王立騎士団" tabindex="-1">第104条 王立騎士団 <a class="header-anchor" href="#第104条-王立騎士団" aria-label="Permalink to &quot;第104条 王立騎士団&quot;">​</a></h3><ol><li>王立騎士団を設置する。</li><li>騎士は弱者を守り名誉を重んじる。</li></ol><h3 id="第105条-叙任" tabindex="-1">第105条 叙任 <a class="header-anchor" href="#第105条-叙任" aria-label="Permalink to &quot;第105条 叙任&quot;">​</a></h3><ol><li>騎士は国王のみが任命できる。</li><li>功績ある平民も叙任できる。</li></ol><h3 id="第106条-騎士道" tabindex="-1">第106条 騎士道 <a class="header-anchor" href="#第106条-騎士道" aria-label="Permalink to &quot;第106条 騎士道&quot;">​</a></h3><ol><li>名誉を守らなければならない。</li><li>臆病を戒める。</li><li>王国の敵に立ち向かわなければならない。</li></ol><hr><h1 id="第三十九編-王室儀礼法" tabindex="-1">第三十九編 王室儀礼法 <a class="header-anchor" href="#第三十九編-王室儀礼法" aria-label="Permalink to &quot;第三十九編 王室儀礼法&quot;">​</a></h1><h2 id="第一章-王室行事" tabindex="-1">第一章 王室行事 <a class="header-anchor" href="#第一章-王室行事" aria-label="Permalink to &quot;第一章 王室行事&quot;">​</a></h2><h3 id="第107条-謁見" tabindex="-1">第107条 謁見 <a class="header-anchor" href="#第107条-謁見" aria-label="Permalink to &quot;第107条 謁見&quot;">​</a></h3><ol><li>国王への謁見には許可を要する。</li><li>宮殿内への武器持ち込みを禁ずる。</li></ol><h3 id="第108条-戴冠式" tabindex="-1">第108条 戴冠式 <a class="header-anchor" href="#第108条-戴冠式" aria-label="Permalink to &quot;第108条 戴冠式&quot;">​</a></h3><ol><li>新国王は戴冠式を行う。</li><li>戴冠の日を祝日とする。</li></ol><h3 id="第109条-王室紋章" tabindex="-1">第109条 王室紋章 <a class="header-anchor" href="#第109条-王室紋章" aria-label="Permalink to &quot;第109条 王室紋章&quot;">​</a></h3><ol><li>王室紋章を法的に保護する。</li><li>無断使用を禁ずる。</li></ol><hr><h1 id="第四十編-宗教法" tabindex="-1">第四十編 宗教法 <a class="header-anchor" href="#第四十編-宗教法" aria-label="Permalink to &quot;第四十編 宗教法&quot;">​</a></h1><h2 id="第一章-信仰" tabindex="-1">第一章 信仰 <a class="header-anchor" href="#第一章-信仰" aria-label="Permalink to &quot;第一章 信仰&quot;">​</a></h2><h3 id="第110条-黄金神殿" tabindex="-1">第110条 黄金神殿 <a class="header-anchor" href="#第110条-黄金神殿" aria-label="Permalink to &quot;第110条 黄金神殿&quot;">​</a></h3><ol><li>黄金神殿を国家遺産とする。</li><li>国民は自由に参拝できる。</li></ol><h3 id="第111条-信仰の自由" tabindex="-1">第111条 信仰の自由 <a class="header-anchor" href="#第111条-信仰の自由" aria-label="Permalink to &quot;第111条 信仰の自由&quot;">​</a></h3><ol><li>国民は自由に信仰を選択できる。</li><li>強制改宗を禁ずる。</li></ol><h3 id="第112条-宗教祭典" tabindex="-1">第112条 宗教祭典 <a class="header-anchor" href="#第112条-宗教祭典" aria-label="Permalink to &quot;第112条 宗教祭典&quot;">​</a></h3><ol><li>黄金祭を毎年実施する。</li><li>国家は祭典を支援する。</li></ol><hr><h1 id="第四十一編-魔法・ポーション法" tabindex="-1">第四十一編 魔法・ポーション法 <a class="header-anchor" href="#第四十一編-魔法・ポーション法" aria-label="Permalink to &quot;第四十一編 魔法・ポーション法&quot;">​</a></h1><h2 id="第一章-錬金術" tabindex="-1">第一章 錬金術 <a class="header-anchor" href="#第一章-錬金術" aria-label="Permalink to &quot;第一章 錬金術&quot;">​</a></h2><h3 id="第113条-製造" tabindex="-1">第113条 製造 <a class="header-anchor" href="#第113条-製造" aria-label="Permalink to &quot;第113条 製造&quot;">​</a></h3><ol><li>ポーション製造には登録を要する。</li><li>認定錬金術師が監督する。</li></ol><h3 id="第114条-危険物" tabindex="-1">第114条 危険物 <a class="header-anchor" href="#第114条-危険物" aria-label="Permalink to &quot;第114条 危険物&quot;">​</a></h3><ol><li>危険薬品の無許可販売を禁ずる。</li><li>王室は危険物を没収できる。</li></ol><h3 id="第115条-エンチャント" tabindex="-1">第115条 エンチャント <a class="header-anchor" href="#第115条-エンチャント" aria-label="Permalink to &quot;第115条 エンチャント&quot;">​</a></h3><ol><li>エンチャント技術を保護する。</li><li>偽造エンチャント品を禁ずる。</li></ol><hr><h1 id="第四十二編-警察法" tabindex="-1">第四十二編 警察法 <a class="header-anchor" href="#第四十二編-警察法" aria-label="Permalink to &quot;第四十二編 警察法&quot;">​</a></h1><h2 id="第一章-治安維持" tabindex="-1">第一章 治安維持 <a class="header-anchor" href="#第一章-治安維持" aria-label="Permalink to &quot;第一章 治安維持&quot;">​</a></h2><h3 id="第116条-王立警察隊" tabindex="-1">第116条 王立警察隊 <a class="header-anchor" href="#第116条-王立警察隊" aria-label="Permalink to &quot;第116条 王立警察隊&quot;">​</a></h3><ol><li>王立警察隊を設置する。</li><li>国民と財産を保護する。</li></ol><h3 id="第117条-捜査" tabindex="-1">第117条 捜査 <a class="header-anchor" href="#第117条-捜査" aria-label="Permalink to &quot;第117条 捜査&quot;">​</a></h3><ol><li>捜査は法に基づいて行う。</li><li>虚偽告発を禁ずる。</li></ol><h3 id="第118条-緊急対応" tabindex="-1">第118条 緊急対応 <a class="header-anchor" href="#第118条-緊急対応" aria-label="Permalink to &quot;第118条 緊急対応&quot;">​</a></h3><ol><li>非常時には軍と協力する。</li><li>国民の安全を最優先とする。</li></ol><hr><h1 id="第四十三編-司法法" tabindex="-1">第四十三編 司法法 <a class="header-anchor" href="#第四十三編-司法法" aria-label="Permalink to &quot;第四十三編 司法法&quot;">​</a></h1><h2 id="第一章-裁判所" tabindex="-1">第一章 裁判所 <a class="header-anchor" href="#第一章-裁判所" aria-label="Permalink to &quot;第一章 裁判所&quot;">​</a></h2><h3 id="第119条-裁判所" tabindex="-1">第119条 裁判所 <a class="header-anchor" href="#第119条-裁判所" aria-label="Permalink to &quot;第119条 裁判所&quot;">​</a></h3><ol><li>最高王立裁判所を設置する。</li><li>各州に地方裁判所を設置する。</li></ol><h3 id="第120条-裁判官" tabindex="-1">第120条 裁判官 <a class="header-anchor" href="#第120条-裁判官" aria-label="Permalink to &quot;第120条 裁判官&quot;">​</a></h3><ol><li>裁判官は職務上独立する。</li><li>国王が任命する。</li></ol><h3 id="第121条-弁護" tabindex="-1">第121条 弁護 <a class="header-anchor" href="#第121条-弁護" aria-label="Permalink to &quot;第121条 弁護&quot;">​</a></h3><ol><li>被告人は弁護人を選任できる。</li><li>貧困者には公選弁護人を付す。</li></ol><hr><h1 id="第四十四編-刑務法" tabindex="-1">第四十四編 刑務法 <a class="header-anchor" href="#第四十四編-刑務法" aria-label="Permalink to &quot;第四十四編 刑務法&quot;">​</a></h1><h2 id="第一章-刑務制度" tabindex="-1">第一章 刑務制度 <a class="header-anchor" href="#第一章-刑務制度" aria-label="Permalink to &quot;第一章 刑務制度&quot;">​</a></h2><h3 id="第122条-矯正施設" tabindex="-1">第122条 矯正施設 <a class="header-anchor" href="#第122条-矯正施設" aria-label="Permalink to &quot;第122条 矯正施設&quot;">​</a></h3><ol><li>王立矯正施設を設置する。</li><li>刑務の目的は更生とする。</li></ol><h3 id="第123条-労働" tabindex="-1">第123条 労働 <a class="header-anchor" href="#第123条-労働" aria-label="Permalink to &quot;第123条 労働&quot;">​</a></h3><ol><li>囚人は労働を行える。</li><li>安全基準を守らなければならない。</li></ol><h3 id="第124条-仮釈放" tabindex="-1">第124条 仮釈放 <a class="header-anchor" href="#第124条-仮釈放" aria-label="Permalink to &quot;第124条 仮釈放&quot;">​</a></h3><ol><li>模範囚には仮釈放を認める。</li><li>法務大臣が最終決定する。</li></ol><hr><h1 id="第四十五編-情報機関法" tabindex="-1">第四十五編 情報機関法 <a class="header-anchor" href="#第四十五編-情報機関法" aria-label="Permalink to &quot;第四十五編 情報機関法&quot;">​</a></h1><h2 id="第一章-情報機関" tabindex="-1">第一章 情報機関 <a class="header-anchor" href="#第一章-情報機関" aria-label="Permalink to &quot;第一章 情報機関&quot;">​</a></h2><h3 id="第125条-王立情報局" tabindex="-1">第125条 王立情報局 <a class="header-anchor" href="#第125条-王立情報局" aria-label="Permalink to &quot;第125条 王立情報局&quot;">​</a></h3><ol><li>王立情報局を設置する。</li><li>王国の安全を守る。</li></ol><h3 id="第126条-工作員" tabindex="-1">第126条 工作員 <a class="header-anchor" href="#第126条-工作員" aria-label="Permalink to &quot;第126条 工作員&quot;">​</a></h3><ol><li>工作員は守秘義務を負う。</li><li>身元は機密とする。</li></ol><h3 id="第127条-防諜" tabindex="-1">第127条 防諜 <a class="header-anchor" href="#第127条-防諜" aria-label="Permalink to &quot;第127条 防諜&quot;">​</a></h3><ol><li>敵対勢力の諜報活動を阻止する。</li><li>国家への脅威を調査する。</li></ol><hr><h1 id="第四十六編-国家機密法" tabindex="-1">第四十六編 国家機密法 <a class="header-anchor" href="#第四十六編-国家機密法" aria-label="Permalink to &quot;第四十六編 国家機密法&quot;">​</a></h1><h2 id="第一章-機密" tabindex="-1">第一章 機密 <a class="header-anchor" href="#第一章-機密" aria-label="Permalink to &quot;第一章 機密&quot;">​</a></h2><h3 id="第128条-国家機密" tabindex="-1">第128条 国家機密 <a class="header-anchor" href="#第128条-国家機密" aria-label="Permalink to &quot;第128条 国家機密&quot;">​</a></h3><ol><li>軍事機密を保護する。</li><li>外交機密を保護する。</li></ol><h3 id="第129条-機密区分" tabindex="-1">第129条 機密区分 <a class="header-anchor" href="#第129条-機密区分" aria-label="Permalink to &quot;第129条 機密区分&quot;">​</a></h3><ol><li>機密文書に等級を設定する。</li><li>国王は最高機密を指定できる。</li></ol><h3 id="第130条-閲覧" tabindex="-1">第130条 閲覧 <a class="header-anchor" href="#第130条-閲覧" aria-label="Permalink to &quot;第130条 閲覧&quot;">​</a></h3><ol><li>許可された者のみ閲覧できる。</li><li>無断複製を禁ずる。</li></ol><hr><h1 id="第四十七編-博物館法" tabindex="-1">第四十七編 博物館法 <a class="header-anchor" href="#第四十七編-博物館法" aria-label="Permalink to &quot;第四十七編 博物館法&quot;">​</a></h1><h2 id="第一章-博物館" tabindex="-1">第一章 博物館 <a class="header-anchor" href="#第一章-博物館" aria-label="Permalink to &quot;第一章 博物館&quot;">​</a></h2><h3 id="第131条-王立博物館" tabindex="-1">第131条 王立博物館 <a class="header-anchor" href="#第131条-王立博物館" aria-label="Permalink to &quot;第131条 王立博物館&quot;">​</a></h3><ol><li>王立博物館を設置する。</li><li>歴史資料を保存する。</li></ol><h3 id="第132条-寄贈" tabindex="-1">第132条 寄贈 <a class="header-anchor" href="#第132条-寄贈" aria-label="Permalink to &quot;第132条 寄贈&quot;">​</a></h3><ol><li>国民は資料を寄贈できる。</li><li>功績に応じて表彰できる。</li></ol><hr><h1 id="第四十八編-図書館法" tabindex="-1">第四十八編 図書館法 <a class="header-anchor" href="#第四十八編-図書館法" aria-label="Permalink to &quot;第四十八編 図書館法&quot;">​</a></h1><h2 id="第一章-図書館" tabindex="-1">第一章 図書館 <a class="header-anchor" href="#第一章-図書館" aria-label="Permalink to &quot;第一章 図書館&quot;">​</a></h2><h3 id="第133条-王立図書館" tabindex="-1">第133条 王立図書館 <a class="header-anchor" href="#第133条-王立図書館" aria-label="Permalink to &quot;第133条 王立図書館&quot;">​</a></h3><ol><li>王立図書館を設置する。</li><li>書籍及び文書を保存する。</li></ol><h3 id="第134条-利用" tabindex="-1">第134条 利用 <a class="header-anchor" href="#第134条-利用" aria-label="Permalink to &quot;第134条 利用&quot;">​</a></h3><ol><li>国民は自由に利用できる。</li><li>貸出規則を守らなければならない。</li></ol><hr><h1 id="第四十九編-報道法" tabindex="-1">第四十九編 報道法 <a class="header-anchor" href="#第四十九編-報道法" aria-label="Permalink to &quot;第四十九編 報道法&quot;">​</a></h1><h2 id="第一章-報道" tabindex="-1">第一章 報道 <a class="header-anchor" href="#第一章-報道" aria-label="Permalink to &quot;第一章 報道&quot;">​</a></h2><h3 id="第135条-報道機関" tabindex="-1">第135条 報道機関 <a class="header-anchor" href="#第135条-報道機関" aria-label="Permalink to &quot;第135条 報道機関&quot;">​</a></h3><ol><li>報道機関を認める。</li><li>虚偽報道を禁ずる。</li></ol><h3 id="第136条-王立広報局" tabindex="-1">第136条 王立広報局 <a class="header-anchor" href="#第136条-王立広報局" aria-label="Permalink to &quot;第136条 王立広報局&quot;">​</a></h3><ol><li>王立広報局を設置する。</li><li>国家情報を公表する。</li></ol><hr><h1 id="第五十編-芸術法" tabindex="-1">第五十編 芸術法 <a class="header-anchor" href="#第五十編-芸術法" aria-label="Permalink to &quot;第五十編 芸術法&quot;">​</a></h1><h2 id="第一章-芸術" tabindex="-1">第一章 芸術 <a class="header-anchor" href="#第一章-芸術" aria-label="Permalink to &quot;第一章 芸術&quot;">​</a></h2><h3 id="第137条-芸術活動" tabindex="-1">第137条 芸術活動 <a class="header-anchor" href="#第137条-芸術活動" aria-label="Permalink to &quot;第137条 芸術活動&quot;">​</a></h3><ol><li>芸術活動を保護する。</li><li>創作の自由を認める。</li></ol><h3 id="第138条-王立劇場" tabindex="-1">第138条 王立劇場 <a class="header-anchor" href="#第138条-王立劇場" aria-label="Permalink to &quot;第138条 王立劇場&quot;">​</a></h3><ol><li>王立劇場を設置する。</li><li>芸術文化の発展を支援する。</li></ol><hr><h1 id="第五十一編-暦法" tabindex="-1">第五十一編 暦法 <a class="header-anchor" href="#第五十一編-暦法" aria-label="Permalink to &quot;第五十一編 暦法&quot;">​</a></h1><h2 id="第一章-王国暦" tabindex="-1">第一章 王国暦 <a class="header-anchor" href="#第一章-王国暦" aria-label="Permalink to &quot;第一章 王国暦&quot;">​</a></h2><h3 id="第139条-王国暦" tabindex="-1">第139条 王国暦 <a class="header-anchor" href="#第139条-王国暦" aria-label="Permalink to &quot;第139条 王国暦&quot;">​</a></h3><ol><li>建国年を元年とする。</li><li>公文書は王国暦を使用する。</li></ol><h3 id="第140条-祝祭日" tabindex="-1">第140条 祝祭日 <a class="header-anchor" href="#第140条-祝祭日" aria-label="Permalink to &quot;第140条 祝祭日&quot;">​</a></h3><ol><li>建国記念日</li><li>黄金祭</li><li>戴冠記念日</li></ol><hr><h1 id="第五十二編-栄典法" tabindex="-1">第五十二編 栄典法 <a class="header-anchor" href="#第五十二編-栄典法" aria-label="Permalink to &quot;第五十二編 栄典法&quot;">​</a></h1><h2 id="第一章-栄誉" tabindex="-1">第一章 栄誉 <a class="header-anchor" href="#第一章-栄誉" aria-label="Permalink to &quot;第一章 栄誉&quot;">​</a></h2><h3 id="第141条-名誉騎士" tabindex="-1">第141条 名誉騎士 <a class="header-anchor" href="#第141条-名誉騎士" aria-label="Permalink to &quot;第141条 名誉騎士&quot;">​</a></h3><ol><li>功績者を名誉騎士に任命できる。</li></ol><h3 id="第142条-黄金十字勲章" tabindex="-1">第142条 黄金十字勲章 <a class="header-anchor" href="#第142条-黄金十字勲章" aria-label="Permalink to &quot;第142条 黄金十字勲章&quot;">​</a></h3><ol><li>軍事功績者に授与する。</li></ol><h3 id="第143条-王国功労勲章" tabindex="-1">第143条 王国功労勲章 <a class="header-anchor" href="#第143条-王国功労勲章" aria-label="Permalink to &quot;第143条 王国功労勲章&quot;">​</a></h3><ol><li>科学・文化への貢献者に授与する。</li></ol><hr><h1 id="第五十三編-国家象徴法" tabindex="-1">第五十三編 国家象徴法 <a class="header-anchor" href="#第五十三編-国家象徴法" aria-label="Permalink to &quot;第五十三編 国家象徴法&quot;">​</a></h1><h2 id="第一章-国家象徴" tabindex="-1">第一章 国家象徴 <a class="header-anchor" href="#第一章-国家象徴" aria-label="Permalink to &quot;第一章 国家象徴&quot;">​</a></h2><h3 id="第144条-国歌" tabindex="-1">第144条 国歌 <a class="header-anchor" href="#第144条-国歌" aria-label="Permalink to &quot;第144条 国歌&quot;">​</a></h3><ol><li>国歌を「Glory of Gold」とする。</li></ol><h3 id="第145条-国旗" tabindex="-1">第145条 国旗 <a class="header-anchor" href="#第145条-国旗" aria-label="Permalink to &quot;第145条 国旗&quot;">​</a></h3><ol><li>国旗中央に王室紋章を配置する。</li></ol><h3 id="第146条-国璽" tabindex="-1">第146条 国璽 <a class="header-anchor" href="#第146条-国璽" aria-label="Permalink to &quot;第146条 国璽&quot;">​</a></h3><ol><li>国璽を国家権威の象徴とする。</li></ol><hr><h1 id="第五十四編-言語法" tabindex="-1">第五十四編 言語法 <a class="header-anchor" href="#第五十四編-言語法" aria-label="Permalink to &quot;第五十四編 言語法&quot;">​</a></h1><h2 id="第一章-公用語" tabindex="-1">第一章 公用語 <a class="header-anchor" href="#第一章-公用語" aria-label="Permalink to &quot;第一章 公用語&quot;">​</a></h2><h3 id="第147条-公用語" tabindex="-1">第147条 公用語 <a class="header-anchor" href="#第147条-公用語" aria-label="Permalink to &quot;第147条 公用語&quot;">​</a></h3><ol><li>ピグリン語及び共通語を公用語とする。</li></ol><h3 id="第148条-公文書" tabindex="-1">第148条 公文書 <a class="header-anchor" href="#第148条-公文書" aria-label="Permalink to &quot;第148条 公文書&quot;">​</a></h3><ol><li>公文書は両言語で作成できる。</li></ol><hr><h1 id="第五十五編-公共奉仕法" tabindex="-1">第五十五編 公共奉仕法 <a class="header-anchor" href="#第五十五編-公共奉仕法" aria-label="Permalink to &quot;第五十五編 公共奉仕法&quot;">​</a></h1><h2 id="第一章-奉仕" tabindex="-1">第一章 奉仕 <a class="header-anchor" href="#第一章-奉仕" aria-label="Permalink to &quot;第一章 奉仕&quot;">​</a></h2><h3 id="第149条-公共奉仕" tabindex="-1">第149条 公共奉仕 <a class="header-anchor" href="#第149条-公共奉仕" aria-label="Permalink to &quot;第149条 公共奉仕&quot;">​</a></h3><ol><li>国民は地域社会への奉仕に努める。</li><li>国家は公共奉仕を奨励する。</li></ol><h3 id="第150条-栄誉称号" tabindex="-1">第150条 栄誉称号 <a class="header-anchor" href="#第150条-栄誉称号" aria-label="Permalink to &quot;第150条 栄誉称号&quot;">​</a></h3><ol><li>国王は功績者に特別称号を授与できる。</li></ol>',158)])])}const q=l(o,[["render",h]]);export{b as __pageData,q as default};
